#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
typedef vector<ll> vl;
typedef pair<ll,ll> pl;
#define all(x) x.begin(),x.end()
#define allr(x) x.rbegin(),x.rend()
#define sz(x) (ll)x.size()
#define ff first
#define ss second
#define int ll
#define fastio() ios_base::sync_withstdio(false);cin.tie(NULL);cout.tie(NULL)
#define rep(i,a,b) for(ll i=a;i<b;i++)
#define repr(i,a,b) for(ll i=a;i>=b;--)


int32_t main() {
	
	int t;
	cin>>t;
	
	while(t--){
	    int n;
	    cin>>n;
	    
	    vector<int> v(n);
	    for(int i=0;i<n;i++){
	        cin>>v[i];
	    }
	    
	    
        vector<int> diff;
        for(int i=0;i<n-1;i++){
            diff.push_back(abs(v[i+1]-v[i]));
        }
        
        diff.push_back(abs(v[0]-v[n-1]));
        
        sort(all(diff));
        if(n==2){
            cout<<diff[0]<<endl;
        }
        else{
            cout<<diff[diff.size()-2]<<endl;
        }
	}

}
